INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(5164, 'itIT', 'Si è cacciato nei guai frugando tra i rifiuti magici a Lunargenta. Per fortuna, eri lì per dargli una mano!', '|cFFFFD200Scoperta:|r Lunargenta|n', 69497),
(5077, 'itIT', '', '', 69497);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(318840, 'itIT', '', 'Gli spiriti pigliano e gli spiriti tolgono, eh? Tenta la fortuna n\'altra volta.', 69497),
(317406, 'itIT', '(urla di agonia)', '', 69497),
(317402, 'itIT', '(tossisce)', '', 69497),
(317398, 'itIT', '(respiro pesante)', '', 69497),
(318450, 'itIT', '', 'È il nostro bersaglio.', 69497),
(318448, 'itIT', '', 'Nasconditi nelle ombre, presto!', 69497),
(314045, 'itIT', '', 'Non farmi spaventare così.', 69497),
(314044, 'itIT', '', 'Torna a combattere.', 69497),
(314043, 'itIT', '', 'Se combatti con me, combatti fino alla fine.', 69497),
(314042, 'itIT', '', 'Ehi, non morire!', 69497),
(314010, 'itIT', '', 'Indietro! Dobbiamo raggrupparci.', 69497),
(313727, 'itIT', '', 'Ti coprirò le spalle.', 69497),
(313723, 'itIT', '', 'Uccidila e potenziami!', 69497),
(313717, 'itIT', '', 'C\'è solo una Valeera. Abbattila!', 69497),
(321873, 'itIT', '', 'Tienile la mano.', 69497),
(320494, 'itIT', '', 'Grazie, $n. Anche se non hai potuto salvarli, chiste informazioni salveranno tante vite assai.', 69497),
(319326, 'itIT', '1... 2... 3...\n\nOh! Ehm... ciao!\n\nStavamo solo giocando a nascondino. Gli altri sono nascosti al momento. Si nascondono sempre senza di me perché dicono che sono troppo facile da trovare...\n\nPerò mi sembra che tu ci sappia fare a nascondino! Molto meglio di me...\n\nVuoi provare a cercarli?\n\nTi avviso, però... si nascondono davvero bene.\n\n5... 6... 7...', '1... 2... 3...\n\nOh! Ehm... ciao!\n\nStavamo solo giocando a nascondino. Gli altri sono nascosti al momento. Si nascondono sempre senza di me perché dicono che sono troppo facile da trovare...\n\nPerò mi sembra che tu ci sappia fare a nascondino! Molto meglio di me...\n\nVuoi provare a cercarli?\n\nTi avviso, però... si nascondono davvero bene.\n\n5... 6... 7...', 69497),
(318831, 'itIT', 'Ladri...', '', 69497),
(318533, 'itIT', '', 'Tutto chello che abbiamo passato...\n\nNun può andare sprecato.', 69497),
(318238, 'itIT', 'Cosa?!? Ha ucciso l\'intero villaggio? Ma che razza di Loa...', '', 69497),
(317991, 'itIT', 'Ti prego! Se non usi quel desiderio, sarò bloccato qui per sempre! Ti darò qualsiasi cosa! Devi solo chiederlo!', '', 69497),
(317886, 'itIT', 'Che gentile da parte tua salvare questa vecchia volpe! Mi hai dato un dono, quindi ti ricambierò il favore del triplo! Tre benedizioni per te.\n\nQuale vuoi che sia la prima?', '', 69497),
(317371, 'itIT', 'I miei... I miei genitori...', '', 69497),
(317362, 'itIT', 'Concentrati.', '', 69497),
(316476, 'itIT', 'Hanno tradito il nonno, lo zio, e tradiranno pure a te.', '', 69497),
(316469, 'itIT', '', 'Perché lo stai facendo?', 69497),
(316440, 'itIT', 'Quando osservo il Vuoto, sai cosa vedo?', '', 69497),
(315773, 'itIT', 'GOL! Che finale per chesta giornata di pallateschio piena di azione! Chesta partita verrà scritta nella storia, amici, e io nun me la dimenticherò mai.', '', 69497),
(315751, 'itIT', 'Che movimento di gambe! Che movimento di testa!', '', 69497),
(315736, 'itIT', 'Signore e gentilcumpà, è ora di assistere ancora na volta al gioco dei re, e il re dei giochi: pallateschio!', '', 69497),
(315715, 'itIT', 'Le leggende dicono che ci sono voluti DUE Stregoni per evocare il prossimo avversario! È grosso, è blu e preferirebbe nun stare accà! È Guth\'kar!', '', 69497),
(315706, 'itIT', 'Anche na squadra di disperati potrebbe... n\'attimo, ma chelli sono $unu bello:na bella; $PR e n\'Elfa senza pantaloni? Pure loro potrebbero farcela!', '', 69497),
(314378, 'itIT', 'Che l\'esperimento... abbia inizio!', '', 69497),
(313757, 'itIT', 'È bello vedere delle facce nuove da queste parti. Io e la mia ciurma siamo rimasti isolati per oltre sette anni, e abbiamo iniziato a pensare di dover ricostruire la società da zero!', '', 69497),
(313655, 'itIT', 'Il veleno va a fondo. Carne ed ossa!', '', 69497),
(313623, 'itIT', '', 'Orweyna? Mo\' stai parlando con Nek\'zali. Inchinati e ti lascerò vivere.', 69497),
(313438, 'itIT', '', 'Ora torno ad annoiarmi.', 69497),
(313337, 'itIT', 'Sparite dalla vista mia!', '', 69497),
(313292, 'itIT', 'Tortolliani... puzzano di pesce e di mare. Disgustoso!', '', 69497),
(313265, 'itIT', 'Salvato? E con l\'aiuto di $uno straniero:na straniera;, per di più. Ti sono debitore, $n.', '', 69497),
(313191, 'itIT', 'Salve! Hai proprio l\'aspetto $udel giovane:della giovane; $C che stavo cercando.\n\nMolti dei nostri anziani più riveriti non sono riusciti a fuggire dagli invasori Galladin quando hanno attaccato il nostro accampamento.\n\nI secoli hanno dato loro dei gusci forti e tanti ricordi, ma la loro velocità non è proprio il massimo.\n\nPotresti aiutare alcuni di questi vecchi gusci a fuggire verso la libertà?\n\nE se ti capitasse di trovare alcune reliquie o pergamene che siamo stati costretti ad abbandonare, ci sarebbero davvero utili per ristabilirci nel nostro nuovo accampamento.', 'Salve! Hai proprio l\'aspetto $udel giovane:della giovane; $C che stavo cercando.\n\nMolti dei nostri anziani più riveriti non sono riusciti a fuggire dagli invasori Galladin quando hanno attaccato il nostro accampamento.\n\nI secoli hanno dato loro dei gusci forti e tanti ricordi, ma la loro velocità non è proprio il massimo.\n\nPotresti aiutare alcuni di questi vecchi gusci a fuggire verso la libertà?\n\nE se ti capitasse di trovare alcune reliquie o pergamene che siamo stati costretti ad abbandonare, ci sarebbero davvero utili per ristabilirci nel nostro nuovo accampamento.', 69497),
(313079, 'itIT', 'No! Non è ancora finita...', '', 69497),
(312978, 'itIT', 'Ah! Dopo migliaia d\'anni, sto libero! È ora di trovarmi nu corpo adatto.', '', 69497),
(312896, 'itIT', '', 'Mmh... non hai una bella cera. Mal di testa? Maledizioni? O solo pessime decisioni? Ho qualcosa per tutte e tre, e spesso è la stessa medicina.', 69497),
(312775, 'itIT', '', 'Eheh. Statt\' accuort\', hash\'ura. Stai cominciando a parlare come gli Amani.', 69497),
(312568, 'itIT', 'Cremisi. Vissscoso. <slurp> Delizioso.', '', 69497),
(312407, 'itIT', '', 'Ahah! Allora... state n\'altra volta accà?', 69497),
(312364, 'itIT', '', 'Guardate! La porta si è aperta, finalmente... Sto arrivando, Zul\'jan. Resisti!', 69497),
(312317, 'itIT', 'Stanno cose più spaventose dei serpenti su chest\'isola!', '', 69497),
(312311, 'itIT', 'Chella cosa che tieni... brilla di potere...', '', 69497),
(311954, 'itIT', '', 'Avete trovato... Jan?', 69497),
(311951, 'itIT', 'Affascinante... una vera fonte di angoscia.', '', 69497),
(311938, 'itIT', 'Oh... Hai un aspetto un po\' pallido. Non sarà mica colpa del veleno?', '', 69497),
(311936, 'itIT', 'Il serpente ha perso le zanne. Sei ancora tu a dominare.', '', 69497),
(311893, 'itIT', '', 'Questa scelta sì che merita un brindisi.', 69497),
(311857, 'itIT', 'Un altro giro, eh? Sei il tipo di guai che preferisco. Mi piaci, vecchio panda.', '', 69497),
(311849, 'itIT', 'I guai mi trovano sempre, amico mio, ma anche la birra. Spesso arrivano insieme.', '', 69497),
(311846, 'itIT', 'Posso solo dire che la tua fama è ben meritata. Questa va assaporata lentamente.', '', 69497),
(311845, 'itIT', 'Be\'... cosa ne pensi?', '', 69497),
(311800, 'itIT', '', 'L\'Hash\'ey ti dà il benvenuto.', 69497),
(311779, 'itIT', '', 'Zerenago, onorevole med\'jai. Sono arrivati altri a darci il cambio di guardia.', 69497),
(311769, 'itIT', 'Ah, un\'altra anima errante!', '', 69497),
(311762, 'itIT', '', 'Sta proprio là. Glielo puoi riportare?', 69497),
(311691, 'itIT', 'Teniamo rispetto dei morti, ma l\'ectoplasma ci è utile. Raccogline nu poco da chelli violenti.', '', 69497),
(311583, 'itIT', '', 'Nun possiamo lasciare che i Figli di Ula\'tek se ne vadano a spasso. Uccidili!', 69497),
(311317, 'itIT', '', 'Sto bene, è solo nu graffio. Raggruppiamoci al villaggio.', 69497),
(311250, 'itIT', 'Nun tengono un bel sapore... ma alle truppe nuostr\' farà piacere avere frutta fresca.', '', 69497),
(311241, 'itIT', 'Gli spiriti riposano. Mi assicurerò che le loro armi nun vadano sprecate.', '', 69497),
(310320, 'itIT', '', 'So che vuoi alleviare le mie preoccupazioni, $n. Ma solo di recente ho capito che le mie parole hanno un peso. Ho voluto affrettarmi a riparare le fratture fra la nostra specie, e ora gli Amani ne stanno pagando il prezzo.\n\nVoglio fare la cosa giusta. Insieme.', 69497),
(309826, 'itIT', '', 'No, ormai è andata. Controlla vicino alla nave, forse ci sono ancora alcune anime che vagano sul ponte.', 69497),
(309825, 'itIT', '', 'Jelvik? Mmh, sì. Era nu tipo allegro. Sempre pronto ad aiutare. Era quasi n\'amico...', 69497),
(309540, 'itIT', 'Teniamo da aiutare $n! Tekkan! Nun startene lì impalato!', '', 69497),
(309165, 'itIT', 'Eh. Ancora riponi la fiducia nei Loa? Zul\'jan ormai ha visto qualcosa di chiù forte.', '', 69497),
(309043, 'itIT', '', 'I nostri nemici non si arrendono mai... occupati di questa minaccia, e in fretta!', 69497),
(308482, 'itIT', 'Se Zul\'jan pensa che lo lasceremo governare al posto di Zul\'jarra dopo chesto, mi sa che resterà deluso.', '', 69497),
(308324, 'itIT', '', 'Grande Loa della Vittoria! L\'Hash\'ey degli Amani chiede ancora una volta l\'aiuto tuo!', 69497),
(308186, 'itIT', 'Malacrass dev\'essere nel tempio insieme a Zul\'jan. Mo\' sono entrambi nemici degli Amani.', '', 69497),
(308043, 'itIT', 'Prima la Lama del Crepuscolo era al seguito di Xal\'atath. Sapranno sicuramente dove si trova ora.\n\nE, quando avremo scoperto che cosa sanno, troveremo Xal\'atath e gliela faremo pagare.', '', 69497),
(307747, 'itIT', '', 'Nun mi sembri così forte. Vuoi davvero combattere? Riuscirai a stare al passo?', 69497),
(307386, 'itIT', 'Non so dove sia finita Xal\'atath, ma so che con l\'uccisione di Ula\'tek, Kith\'ix è libero di risorgere!', '', 69497),
(307346, 'itIT', 'Quello è... Antenorian? Impossibile!', '', 69497),
(307324, 'itIT', 'Per Arator, la nostra vittoria al Pozzo dell\'Alba non è importante quanto trovare i suoi genitori... e Xal\'atath.', '', 69497),
(304905, 'itIT', 'Nek\'zali! Accà ci servono le cure tue!', 'Nek\'zali! Accà ci servono le cure tue!', 69497),
(304870, 'itIT', '', 'Nu potere più antico e più grande dei Loa! Con isso, gli Amani trionferanno!', 69497),
(304688, 'itIT', 'Eheh! Questo corpo balla come una marionetta!', '', 69497),
(304072, 'itIT', 'Non passerete. Non dovete vedere.', '', 69497),
(303912, 'itIT', '', 'Deve averci condotti qui per uno scopo.', 69497),
(324314, 'itIT', '', 'Perché non dovrei? Sono una mercante, e ho comprato e venduto merci trattando con tutti i popoli dell\'Alleanza. Qualsiasi cosa sia stata realizzata bene merita il mio interesse. E la tua considerazione.\n\nSe può interessarti, il trattore è stato costruito da uno Gnomo delle Marche Occidentali, non da un Umano.', 69497),
(324310, 'itIT', '', 'Ti do il benvenuto. Offro alcune delle merci migliori importate dalle terre delle Marche Occidentali.', 69497),
(317690, 'itIT', 'Capitano del Nexus Leth\'ir,\n\nNonostante le tue azioni, le quote di processazione del mana di Naigtal stanno superando ogni aspettativa.\n\nPer questo motivo, l\'Autorotum schiererà degli agenti d\'élite per assicurare il successo dell\'operazione Scintilla Arcoceanica.\n\nPanoramica degli agenti:\n\n- Scagliamagie Rem\'lazar - Sovrintendente della Manaforgia Oltani\n- Rinnegato Kulivero - Ex Comandante di Fase\n- Tecnomedica Alazj - Arcatecnomante\n- Guardiano Halazir - Ultimo modello di automatron di Alazj\n- Agente della Distorsione Xi\'grivr - [Redatto]\n- Artiveggente Ahl\'syraz - Architetta del Nulla\n- [Redatto]\n\n- Il console di comunicazione dell\'Autorotum', 'Capitano del Nexus Leth\'ir,\n\nNonostante le tue azioni, le quote di processazione del mana di Naigtal stanno superando ogni aspettativa.\n\nPer questo motivo, l\'Autorotum schiererà degli agenti d\'élite per assicurare il successo dell\'operazione Scintilla Arcoceanica.\n\nPanoramica degli agenti:\n\n- Scagliamagie Rem\'lazar - Sovrintendente della Manaforgia Oltani\n- Rinnegato Kulivero - Ex Comandante di Fase\n- Tecnomedica Alazj - Arcatecnomante\n- Guardiano Halazir - Ultimo modello di automatron di Alazj\n- Agente della Distorsione Xi\'grivr - [Redatto]\n- Artiveggente Ahl\'syraz - Architetta del Nulla\n- [Redatto]\n\n- Il console di comunicazione dell\'Autorotum', 69497),
(317689, 'itIT', 'Capitano del Nexus Leth\'ir,\n\nLe tue azioni recenti sono un chiaro segno d\'insubordinazione e stupidità senza precedenti.\n\nLe tue attività ostili e non autorizzate su Azeroth hanno esposto gli Hal\'hadar.\n\nL\'Autorotum avrebbe tutte le ragioni per spogliarti del tuo rango e gettare la tua forma svincolata nel più vicino sole di Heraazi.\n\nPer tua fortuna, ho saputo convincere i membri a rinunciare.\n\nOra che le manaforge di Naigtal sono operative, hai l\'ordine di interrompere le operazioni su Azeroth e cessare le ostilità.\n\n- Arcancelliere Ahl\'dynsir', '', 69497),
(317687, 'itIT', 'Capitano del Nexus Leth\'ir,\n\nL\'operazione Scintilla Arcoceanica è della massima priorità per l\'Autorotum.\n\nI ritardi del Settore Sodaraam sono dovuti ad azioni ostili da parte dei ribelli menzionati nel registro di comunicazione Beta-J21.\n\nAttendete lo schieramento di rifornimenti e forza lavoro con lo sgombero dei porti di spedizione.\n\n- Il console di comunicazione dell\'Autorotum', 'Capitano del Nexus Leth\'ir,\n\nL\'operazione Scintilla Arcoceanica è della massima priorità per l\'Autorotum.\n\nI ritardi del Settore Sodaraam sono dovuti ad azioni ostili da parte dei ribelli menzionati nel registro di comunicazione Beta-J21.\n\nAttendete lo schieramento di rifornimenti e forza lavoro con lo sgombero dei porti di spedizione.\n\n- Il console di comunicazione dell\'Autorotum', 69497),
(317686, 'itIT', 'Console di comunicazione,\n\nQuesta è la quarta olomissiva che ho inviato senza aver ricevuto risposta.\n\nLa consegna delle celle di mana da Sodaraam deve ancora arrivare e le mie forze sono in attesa di ordini per lo schieramento.\n\nNon possiamo stabilire un\'intera griglia di manaforge, tantomeno una singola tubatura, senza delle celle di mana preliminari.\n\nRichiedo con urgenza e immediatamente un reindirizzamento di celle di mana da altre griglie operative.\n\nVostro umile e paziente servitore,\n\nCapitano del Nexus Leth\'ir', 'Console di comunicazione,\n\nQuesta è la quarta olomissiva che ho inviato senza aver ricevuto risposta.\n\nLa consegna delle celle di mana da Sodaraam deve ancora arrivare e le mie forze sono in attesa di ordini per lo schieramento.\n\nNon possiamo stabilire un\'intera griglia di manaforge, tantomeno una singola tubatura, senza delle celle di mana preliminari.\n\nRichiedo con urgenza e immediatamente un reindirizzamento di celle di mana da altre griglie operative.\n\nVostro umile e paziente servitore,\n\nCapitano del Nexus Leth\'ir', 69497),
(317685, 'itIT', 'Capitano del Nexus Leth\'ir,\n\nsei incaricato di stabilire una rete di manaforge nel mondo designato come \"Naigtal\".\n\nGli oceani di questo mondo mostrano alti livelli di energia arcana e sembrano avere un impatto sui biomi del pianeta.\n\nSaranno schierate nel mondo delle celle di mana preliminari con la prossima spedizione in partenza dal Settore Sodaraam.\n\nL\'operazione Scintilla Arcoceanica è iniziata.\n\n- Il console della comunicazione dell\'Autorotum', '', 69497),
(317350, 'itIT', 'Grazie dell\'aiuto là fuori e degli sforzi che hai fatto per curare La\'una.', '', 69497),
(316943, 'itIT', '', 'Sei stato tu a corromperlo, com\'hai fatto col nonno nuostr\'!', 69497),
(316933, 'itIT', 'Che fiacchezza chisti Amani...', '', 69497),
(316473, 'itIT', 'Uno che incute terrore al nemico. Nun uno che si prostra agli spiriti.', '', 69497),
(315958, 'itIT', 'Che ferocia! Mo\' è stato messo al tappeto per davvero!', '', 69497),
(315957, 'itIT', 'Che sta succedendo? È stato tokkato, ma si sta rialzando? Non c\'è modo di tenerlo a terra!', '', 69497),
(315955, 'itIT', 'È il primo primate, il mitico macaco, il grande gorilla in persona! Tok!', '', 69497),
(315953, 'itIT', 'Tok!', 'Tok!', 69497),
(315951, 'itIT', 'Se dico Tok, voi che dite?', '', 69497),
(315214, 'itIT', '', 'Sì.\n\nSin da quando hai portato la chiave a Belath, ho setacciato i nostri archivi in cerca di informazioni. \n\nQuando ci siamo infiltrati ad Antorus, abbiamo raccolto una grande quantità di informazioni sui diversi mondi conquistati dalla Legione.\n\nOvviamente, senza sapere da quale mondo ha origine questa chiave, quei rapporti potrebbero risultare inutili.', 69497),
(315085, 'itIT', '', 'Nun ti potrò mai ringraziare abbastanza, $p.\n\nIl tuo aiuto nel trovare na cura per La\'una e a cercare il resto della squadra nuostr\'. Significa assai per noi.', 69497),
(315002, 'itIT', 'Scommetto che riesco ad arrivare al foro prima di te. Ti darò anche un po\' di vantaggio.', '', 69497),
(313066, 'itIT', 'Tutta chista fatica per niente.', '', 69497),
(313039, 'itIT', '', 'La barriera si sta indebolendo!', 69497),
(313036, 'itIT', '', 'Zul\'jarra non ha molto tempo. Io vado avanti, tu abbatti le barriere, $n!', 69497),
(312774, 'itIT', '', 'Jan si comportava sempre come se tenesse gli occhi degli antenati addosso. Li voleva rendere orgogliosi.', 69497),
(311940, 'itIT', 'Astuto e coraggioso fino alla fine. Non posso che avere rispetto, ma può esserci un solo vincitore.', '', 69497),
(311615, 'itIT', 'Anche se non sa usare il Vuoto, la sua determinazione nel trovare Xal\'atath gli dà la forza di resistere alla sua presenza anche quando richiama la Luce.', '', 69497),
(311605, 'itIT', 'C\'è chi accusa me, e tutti gli Elfi del Vuoto, di essere dei mostri. Non voglio dare loro ragione.', '', 69497),
(310494, 'itIT', '', 'Ancora ve lo ricordate il ritmo, vero?', 69497),
(308371, 'itIT', '', 'Un attimo. Sento... la voce della dea! Ci sta chiamando...', 69497),
(307753, 'itIT', 'Mo\' aspiriamo l\'anima dalle ossa. Butta l\'esca!', '', 69497),
(307646, 'itIT', '', 'Ricordo solo che cercavo la gloria chillo giorno, ma ho dimenticato il motivo per cui combattevo.', 69497),
(307379, 'itIT', 'Indubbiamente. E scommetto che Antenorian sa come intendono farlo.', '', 69497),
(307367, 'itIT', 'Aaagh! No!', '', 69497),
(305873, 'itIT', '', 'Tefokal nun è messo così male, ma devo occuparmi delle ferite sue prima che si infettino.', 69497),
(304867, 'itIT', 'Ritirata! Portate i feriti al rifugio!', '', 69497),
(304624, 'itIT', '', 'Silenzio! E stammi vicina stavolta.', 69497),
(308552, 'itIT', 'Nun si pote venerare! Si può solo dimenticare!', '', 69497);
