INSERT INTO `currency_types_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3356, 'itIT', 'Cristalli di Mana Incontaminati', 'Ottenibile dopo aver raggiunto il Grado 9 dei Viaggi nelle Scorribande, aprendo Scrigni Fruttuosi con Chiavi dello Scrigno Ripristinate nelle Scorribande Fruttuose al Grado 11. Scambiabile da Zah\'ran con potente equipaggiamento.', 69497),
(3418, 'itIT', 'Nucleo del Vuoto Nebuloso', 'Trasmutabile in equipaggiamenti potenti dopo aver sconfitto grandi nemici nelle incursioni di Midnight o completando spedizioni Mitiche+, Scorribande Fruttuose e Cacce alla Preda in modalità Incubo.\n\nGli oggetti si possono ricevere solo una volta per livello di difficoltà finché tutti gli oggetti potenziali per la specializzazione attuale non sono stati trasmutati.', 69497),
(3509, 'itIT', 'Polvere di Scintilla delle Maree', 'Un residuo magico ottenuto dalle Scintille delle Maree, usato per tenere traccia di quante Scintille delle Maree hai ottenuto finora nella Stagione 2 di Midnight.\n\nSe rimani indietro con le Scintille durante la Stagione, completare contenuti di livello massimo come le Scorribande, le spedizioni Mitiche+, le incursioni, il PvP istanziato e alcuni eventi del mondo esterno può aiutarti a recuperare.', 69497);
