INSERT INTO `scenario_step_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `VerifiedBuild`) VALUES
(17053, 'itIT', 'Entra nelle camere maledette sotto il Sigillo della Collera ed elimina le minacce al loro interno.', 'Ripulisci le Profondità Maledette', 69497),
(17052, 'itIT', 'Trova un modo per entrare nelle Profondità Maledette.', 'Entra nelle Profondità Maledette', 69497),
(17048, 'itIT', 'Preparati ad attaccare i Sotterranei.', 'Preparati all\'Attacco', 69497),
(17044, 'itIT', 'Entra nei Sotterranei e sconfiggi i nemici all\'interno.', 'Ripulisci i Sotterranei', 69497),
(17032, 'itIT', 'Preparati, un\'ondata di serpenti si erge.', 'Serpeggiando dalle Profondità', 69497),
(17030, 'itIT', 'I Curafiamma stanno preparando le Pire Spirituali.', 'Preparare le Pire', 69497),
(17028, 'itIT', 'È stata scoperta una strana cassa!', 'Esamina la Cassa', 69497),
(16919, 'itIT', 'Entra nei portali e distruggi le Uova di Ruuk\'jar.', 'Distruggi la Covata', 69497),
(16918, 'itIT', 'Aspetta che il portale si apra.', 'Evoca il Portale', 69497),
(16876, 'itIT', 'Cassa sbloccata.', 'Cassa Sbloccata', 69497),
(16875, 'itIT', 'Trasporta le tre verghe da ciascuna pietra alla cassa.', 'Recupera i Bastoni', 69497),
(16873, 'itIT', 'Raduna gli Spiriti Malevoli e bruciali alle Pire Spirituali. Trasporta le fiamme dalle pire per distruggere i Sarcofagi Profanati.', 'Epura i Non Morti', 69497),
(16858, 'itIT', 'Usa i Santuari per raccogliere i Globi d\'Impurità.', 'Usa il Santuario della Terra e il Santuario del Cielo', 69497),
(16856, 'itIT', 'Uccidi i serpenti e interrompi i rituali prima che invadano il tempio.', 'Argina l\'Ondata di Serpenti', 69497),
(16853, 'itIT', 'I santuari vengono potenziati per l\'uso.', 'Potenzia i Santuari', 69497),
(17336, 'itIT', 'Combatti fino al centro degli Abissi Velenosi e impedisci a Ula\'tek di fuggire dalla sua prigione.', 'Tomba di Ula\'tek', 69497),
(17329, 'itIT', 'Combatti fino al cuore degli Abissi Velenosi e affronta Ula\'tek faccia a faccia.', 'Tomba di Ula\'tek', 69497),
(17328, 'itIT', 'Mostruosità serpentine abitano le antiche sale che custodivano le vittime degli Spiranima.', 'Tana del Serpente', 69497),
